code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] == 0:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c = q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc = r+dr,c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r,c) not in seen:
                # Enclosed color is selected by the frame's outer side length.
                # Determine the enclosing component's bounding box from its zeros and border.
                out[r][c] = 8
    # Assign colors by enclosed region dimensions (the examples use square frames).
    visited = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen or (r,c) in visited:
                continue
            comp=[]; st=[(r,c)]; visited.add((r,c))
            while st:
                x,y=st.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<h and 0<=yy<w and grid[xx][yy]==0 and (xx,yy) not in seen and (xx,yy) not in visited:
