            # Interior width/height: 3 -> 8, 5 -> 4, 7 -> 3; larger interior -> 3.
            hh=max(x for x,y in comp)-min(x for x,y in comp)+1
            ww=max(y for x,y in comp)-min(y for x,y in comp)+1
            color = 8 if max(hh,ww) <= 3 else (4 if max(hh,ww) <= 5 else 3)
            for x,y in comp: out[x][y]=color
    return out
